public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (genericType instanceof ParameterizedType) {
        ParameterizedType paramType = (ParameterizedType) genericType;
        Type[] typeArgs = paramType.getActualTypeArguments();
        Class<?>[] resolvedArgs = new Class<?>[typeArgs.length];
        for (int i = 0; i < typeArgs.length; i++) {
            Type typeArg = typeArgs[i];
            if (typeArg instanceof TypeVariable) {
                TypeVariable typeVar = (TypeVariable) typeArg;
                resolvedArgs[i] = resolveTypeVariable(typeVar, targetType);
            } else {
                resolvedArgs[i] = (Class<?>) typeArg;
            }
        }
        return resolvedArgs;
    }
    return null;
}

private static Class<?> resolveTypeVariable(TypeVariable typeVar, Class<?> targetType) {
    Type[] bounds = typeVar.getBounds();
    for (Type bound : bounds) {
        if (bound instanceof Class) {
            return (Class<?>) bound;
        } else if (bound instanceof ParameterizedType) {
            ParameterizedType paramType = (ParameterizedType) bound;
            return (Class<?>) paramType.getRawType();
        }
    }
    return null;
}

