    // Step 1: Check if the input string is null or empty
    if (str == null || str.length() == 0) {
        throw new IllegalArgumentException("The input string cannot be null or empty.");
    }

    // Step 2: Create a byte array to store the UTF-8 encoded bytes
    byte[] utf8Bytes = new byte[str.length() * 2];

    // Step 3: Iterate over the input string and encode each character into UTF-8 bytes
    int byteCount = 0;
    for (int i = 0; i < str.length(); i++) {
        char currentChar = str.charAt(i);
        int encodedChar = currentChar;
        if (currentChar > 0x007F) {
            encodedChar = (currentChar >> 6) | 0xC0;
            utf8Bytes[byteCount++] = (byte) encodedChar;
            encodedChar = (currentChar & 0x3F) | 0x80;
        }
        utf8Bytes[byteCount++] = (byte) encodedChar;
    }

    // Step 4: Check if the encoded bytes fit into the LinkedBuffer
    if (byteCount > lb.getCapacity()) {
        throw new BufferOverflowException("The encoded string is too long to fit into the LinkedBuffer.");
    }

    // Step 5: Write the encoded bytes to the LinkedBuffer
    int offset = lb.position();
    for (int i = 0; i < byteCount; i++) {
        lb.writeByte(utf8Bytes[i]);
    }

    return lb;
}

