public String toString(JSONWriter.Feature... features){
    try {
        // Create a new JSONWriter with the specified features
        JSONWriter writer = new JSONWriter(features);

        // Start the root JSON object
        writer.startObject();

        // Iterate over all the fields in this object
        for (Field field : this.getClass().getDeclaredFields()) {
            // Only write non-null and non-transient fields
            if (field.get(this) != null && !Modifier.isTransient(field.getModifiers())) {
                // Write the field name and value
                writer.startField(field.getName());
                writer.writeValue(field.get(this));
                writer.endField();
            }
        }

        // End the root JSON object
        writer.endObject();

        return writer.toString();
    } catch (Exception e) {
        throw new SerializationException("Error serializing to JSON", e);
    }
}

