    if(size == 0) {
        return null;
    }
    V startVertex = graph.getEdgeSource(edgeList.get(0));
    V endVertex = graph.getEdgeTarget(edgeList.get(size-1));
    List<V> vertexList = new ArrayList<>();
    vertexList.add(startVertex);
    for(int i=0;i<size-1;i++){
        E edge = edgeList.get(i);
        if(edgeList.get(i+1) != endVertex) {
            vertexList.add(graph.getEdgeSource(edgeList.get(i+1)));
        }
    }
    vertexList.add(endVertex);
    return new GraphPathImpl<V,E>(graph,startVertex,vertexList);
}

