    ListNodeImpl<E> current = list.getFirst();
    while (current != null) {
        ListNodeImpl<E> next = current.getNext();
        removeListNode(current);
        current.setPrevious(null);
        current.setNext(null);
        addListNode(current);
        current.setPrevious(this.getLast());
        current.setNext(null);
        current = next;
    }
}

