public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        return null;
    }

    // Get path segments
    String[] pathSegments = path.split("/");
    String[] relativePathSegments = relativePath.split("/");

    // Iterate over relative path segments and update pathSegments as needed
    for (String segment : relativePathSegments) {
        if (segment.equals(".")) {
            // Do nothing
        } else if (segment.equals("..")) {
            // Remove the last path segment
            pathSegments = Arrays.copyOf(pathSegments, pathSegments.length - 1);
        } else {
            // Add the current path segment to the end of the list
            pathSegments = Arrays.copyOf(pathSegments, pathSegments.length + 1);
            pathSegments[pathSegments.length - 1] = segment;
        }
    }

    // Join the path segments back together with "/" separators
    StringBuilder sb = new StringBuilder();
    for (String segment : pathSegments) {
        sb.append(segment);
        sb.append("/");
    }

    // Remove the last "/" separator
    String result = sb.toString();
    result = result.substring(0, result.length() - 1);

    return result;
}

