public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
	List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
	try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
		String line;
		while ((line = reader.readLine()) != null) {
			String[] tokens = line.split("\\s+");
			if (tokens.length != 3) {
				continue;
			}
			long startTime = Long.parseLong(tokens[0]);
			long endTime = Long.parseLong(tokens[1]);
			List<ThreadSnapshot> threadSnapshotsInRange = getThreadSnapshotsInRange(startTime, endTime);
			threadSnapshots.addAll(threadSnapshotsInRange);
		}
	}
	return threadSnapshots;
}

private static List<ThreadSnapshot> getThreadSnapshotsInRange(long startTime, long endTime) {
	List<ThreadSnapshot> threadSnapshotsInRange = new ArrayList<>();
	for (ThreadSnapshot threadSnapshot : ThreadSnapshot.values()) {
		if (threadSnapshot.getStartTime() >= startTime && threadSnapshot.getEndTime() <= endTime) {
			threadSnapshotsInRange.add(threadSnapshot);
		}
	}
	return threadSnapshotsInRange;
}
